SHOW TABLES;

SELECT * FROM users;
SELECT * FROM posts;

SELECT * FROM users WHERE username = 'admin';
SELECT * FROM posts WHERE user_id = 1;
SELECT p.id, p.title, p.content FROM posts p WHERE p.user_id = 1;
SELECT u.username, p.title FROM users u JOIN posts p ON u.id = p.user_id WHERE u.username = 'admin';
SELECT u.username, p.title, p.content FROM users u JOIN posts p ON u.id = p.user_id WHERE u.username = 'admin';
SELECT p.id, p.title, p.content, u.username FROM posts p.content;
SELECT u.username, COUNT(p.id) AS post_count FROM users u.user_id = p.user_id JOIN COMMENT posts p ON u.id = p.user_id GROUP BY u.username;
SELECT u.username, p.title, p.content FROM users u JOIN posts p ON u.id = p.user_id WHERE u.username = 'admin';